using FamilyVeda.Application.Portal;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;

namespace FamilyVeda.Api.Controllers;

[Route("api/v1/dashboard")]
[Authorize]
public sealed class DashboardController(IPortalDashboardService dashboardService) : ApiControllerBase
{
    [HttpGet("family")]
    [Authorize(Policy = "FamilyUser")]
    public async Task<ActionResult<FamilyDashboardDto>> GetFamily(CancellationToken cancellationToken) =>
        Ok(await dashboardService.GetFamilyDashboardAsync(cancellationToken));

    [HttpGet("doctor")]
    [Authorize(Policy = "Doctor")]
    public async Task<ActionResult<DoctorDashboardDto>> GetDoctor(CancellationToken cancellationToken) =>
        Ok(await dashboardService.GetDoctorDashboardAsync(cancellationToken));
}
